// Infrastructure/ServiceRegistration.cs
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public static class ServiceRegistration
{
    public static IServiceCollection AddTimeClockPersistence(this IServiceCollection services, string connectionString)
    {
        services.AddDbContext<TimeClockDbContext>(options => options.UseSqlite(connectionString));
        services.AddScoped<IAsyncClockEntryRepository, EfClockEntryRepository>();
        services.AddScoped<AsyncClockEntryService>();
        return services;
    }
}

// Program.cs registration
builder.Services.AddTimeClockPersistence("Data Source=timeclock.db");

// ServiceRegistrationTests.cs
[Fact]
public void AddTimeClockPersistence_WhenGraphIsComplete_ResolvesAsyncClockEntryService()
{
    ServiceCollection services = new ServiceCollection();
    services.AddTimeClockPersistence("Data Source=:memory:");
    using ServiceProvider provider = services.BuildServiceProvider();
    using IServiceScope scope = provider.CreateScope();
    AsyncClockEntryService service = scope.ServiceProvider.GetRequiredService<AsyncClockEntryService>();
    Assert.NotNull(service);
}
